cd /Users/sameralzubaidi/Desktop/kids_marketplace_app/p2p-kids-marketplace && node --input-type=module <<'NODE'
import 'dotenv/config';
import { createClient } from '@supabase/supabase-js';

const url = process.env.EXPO_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL;
const key = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY;

if (!url || !key) {
  console.log('MISSING_ENV', { hasUrl: Boolean(url), hasKey: Boolean(key) });
  process.exit(2);
}

const supabase = createClient(url, key);

const q = await supabase
  .from('platform_policies')
  .select('*', { count: 'exact', head: true })
  .eq('policy_type', 'privacy_policy');

console.log('POLICY_COUNT', q.count, q.error ? q.error.message : 'ok');

const r1 = await supabase.rpc('get_current_policy', { p_policy_type: 'privacy_policy' });
console.log('RPC_P_PARAM', r1.error ? r1.error.message : `ok:${Array.isArray(r1.data) ? r1.data.length : 'n/a'}`);

const r2 = await supabase.rpc('get_current_policy', { policy_type: 'privacy_policy' });
console.log('RPC_NO_PREFIX', r2.error ? r2.error.message : `ok:${Array.isArray(r2.data) ? r2.data.length : 'n/a'}`);
NODE

